package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathNotImplementedException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl#inverseCumulativeProbability.
 */
public class NormalDistributionImpl_inverseCumulativeProbability_TriageGen1Test {

    private NormalDistributionImpl distribution;
    private static final double DELTA = 1e-10;

    @Before
    public void setUp() {
        // Standard normal distribution (mean=0, sd=1)
        distribution = new NormalDistributionImpl(0.0, 1.0);
    }

    @Test
    public void testInverseCumulativeProbability_PZero() throws Exception {
        double p = 0.0;
        double expected = Double.NEGATIVE_INFINITY;
        double actual = distribution.inverseCumulativeProbability(p);
        Assert.assertEquals("When p is 0, should return Double.NEGATIVE_INFINITY", expected, actual, 0.0);
    }

    @Test
    public void testInverseCumulativeProbability_POne() throws Exception {
        double p = 1.0;
        double expected = Double.POSITIVE_INFINITY;
        double actual = distribution.inverseCumulativeProbability(p);
        Assert.assertEquals("When p is 1, should return Double.POSITIVE_INFINITY", expected, actual, 0.0);
    }

    @Test
    public void testInverseCumulativeProbability_StandardValues() throws Exception {
        // Test for p = 0.5 (Median of standard normal is 0)
        double p = 0.5;
        double expected = 0.0;
        double actual = distribution.inverseCumulativeProbability(p);
        Assert.assertEquals("When p is 0.5, should return mean (0.0)", expected, actual, DELTA);

        // Test for common Z-score (approx 0.8413 for p=0.8)
        p = 0.8413447460685429;
        expected = 1.0;
        actual = distribution.inverseCumulativeProbability(p);
        Assert.assertEquals("When p is approx 0.8413, should return 1.0", expected, actual, 1e-7);
    }

    @Test
    public void testInverseCumulativeProbability_CustomMeanAndSd() throws Exception {
        // Mean = 10, SD = 2. For p=0.5, result should be 10.
        NormalDistributionImpl customDist = new NormalDistributionImpl(10.0, 2.0);
        double p = 0.5;
        double expected = 10.0;
        double actual = customDist.inverseCumulativeProbability(p);
        Assert.assertEquals("When p is 0.5, should return custom mean (10.0)", expected, actual, DELTA);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testInverseCumulativeProbability_PLessThanZero() throws Exception {
        // The super method (NormalDistribution) typically throws MathIllegalArgumentException for p outside [0, 1]
        // Since our method handles 0 and 1 explicitly, values < 0 go to super.
        distribution.inverseCumulativeProbability(-0.1);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testInverseCumulativeProbability_PGreaterThanOne() throws Exception {
        // Values > 1 go to super.
        distribution.inverseCumulativeProbability(1.1);
    }
}
